import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const outFile = join(__dirname, "generated-keygen-config.js");

// The disclosed license-key model's Product token (narrowly scoped: license.validate/read,
// machine.create/read/update/delete only -- nothing that can create/delete licenses or touch
// other products/policies/billing). Sourced from an env var set only in the build environment --
// never committed, since this generated file is gitignored, matching generate-oauth-config.mjs's
// pattern for the same reason (GitHub's push protection rejects a commit containing what looks
// like a live credential).
const productToken = process.env.KEYGEN_PRODUCT_TOKEN ?? "";

writeFileSync(
  outFile,
  `// Auto-generated by electron/generate-keygen-config.mjs at build time -- do not edit, do not commit.\n` +
    `export const KEYGEN_PRODUCT_TOKEN = ${JSON.stringify(productToken)};\n`
);

console.log(productToken ? "Wrote Keygen config (product token present)" : "Wrote empty Keygen config (no env var set)");
